  // These two MUST NEVER be reachable from an ordinary application event in
  // Phase 1 (single failed password, single selfie/document mismatch,
  // ordinary validation error, ordinary network error, a single 429).
  // prefy.js's setState()/setContext() consult this list and refuse to
  // apply either state unless the caller passes the explicit Phase-2
  // override token (which nothing in this phase's integration ever does —
  // see test_prefy.mjs's "cannot trigger" tests).
  var SECURITY_STATES = ['POSSIBLE_FRAUD', 'HACKER_ALERT'];

  // Safe fallback when a context key or state is unrecognized — never a
  // security state, never a silent no-op that could look broken.
  var DEFAULT_STATE = 'HELP';
  var UNKNOWN_CONTEXT_KEY = '_unknown';

  // ═══════════════════════════════════════════════════════════════════════
  // ASSET MAP — the 15 final Prefy images are NOT in this repository (per
  // the read-only audit's finding C). Phase 2 (visual asset integration)
  // supplied the final 15 PNGs — approved, byte-verified against the
  // original files, and installed at assets/prefy/, served through
  // main.py's whitelisted /assets/prefy/{filename} route (only these 15
  // exact filenames are ever served; no path is accepted that isn't in
  // that list).
  //
  // Each PNG is ~307x341-342px, RGBA (transparent background, not a
  // flat-color background needing removal). Dimensions vary by a pixel
  // or two between files — prefy.js renders every one with
  // object-fit:contain inside a fixed-aspect-ratio box, so the small
  // variance never causes stretching or cropping.
  //
  // KNOWN, DISCLOSED IMAGE QUALITY ISSUE (reported, not silently fixed):
  // several of the 15 supplied PNGs (at minimum: attention, error,
  // missing-information, possible-fraud, hacker-alert, thinking, thanks,
  // explaining) show a small sliver of adjacent artwork bleeding in at
  // one or two edges of the transparent canvas — consistent with being
  // cropped from a multi-pose contact sheet without fully isolating each
  // cell. The character itself and its state-specific badge icon are
  // NOT obscured or altered by this; the artifact is a few pixels of a
  // neighboring pose/icon at the outer edge. Per this phase's explicit
  // instruction not to apply destructive filters/redraws to the supplied
  // art, this has been left as-is and is reported here rather than
  // auto-cropped — a real fix requires re-exporting these specific
  // frames with clean isolation, which is outside what this phase is
  // authorized to do to the source images.
  var ASSET_WIDTH = 341;   // documented nominal height-driven box; real
  var ASSET_HEIGHT = 341;  // per-file dimensions are read at render time
  var ASSETS = {};
