      'ctx.organizer.logout.title': 'À bientôt !',
      'ctx.organizer.logout.body': 'Merci d\'utiliser Preferendum. Vous allez être déconnecté dans un instant.',
      'ctx.marketer.panel.overview.title': 'Aperçu du compte',
      'ctx.marketer.auth.login.title': 'Se connecter',
      'ctx.marketer.auth.login.body': 'Connectez-vous ici en tant qu\'annonceur avec votre e-mail et votre mot de passe existants. Première visite ? Utilisez l\'onglet d\'inscription.',
      'ctx.marketer.auth.register.title': 'Créer un compte annonceur',
      'ctx.marketer.auth.register.body': 'Vous créez ici votre compte pour diffuser des campagnes ciblées sur Preferendum — entreprise, e-mail et mot de passe.',
      'ctx.marketer.panel.overview.body': 'Voici un résumé de vos campagnes et de votre solde disponible.',
      'ctx.marketer.panel.credits.title': 'Crédits REAL et DEMO',
