      'ctx.voter.error.generic.title': 'Bir şeyler ters gitti',
      'ctx.voter.error.generic.body': 'Bu işlemi gerçekleştirirken bir sorun oluştu. Bir an sonra tekrar deneyebilirsiniz.',
