      'ctx.voter.register.password.title': 'Kata sandi',
      'ctx.voter.register.password.body': 'Kata sandi Anda melindungi akses ke akun Anda. Kami tidak pernah membagikan atau menampilkannya — bahkan tim kami sendiri pun tidak bisa melihatnya.',
      'ctx.voter.register.national_id.title': 'Dokumen identitas',
