      'chrome.help': 'Nápověda', 'chrome.reopen': 'Znovu vysvětlit tuto obrazovku', 'chrome.name': 'Prefy',
      'chrome.help.whereAmI': 'Kde jsem?', 'chrome.help.whatCanIDo': 'Co tady mohu dělat?',
