      'chrome.voice.unmute': 'Zapnout hlas Prefy',
      'chrome.voice.unavailable': 'Hlas není na tomto zařízení nebo v tomto prohlížeči k dispozici.',
      'ctx.voter.welcome.title': 'Vítejte v Preferendu!',
      'ctx.voter.welcome.body': 'Jsem Prefy, váš průvodce v Preferendu. Během postupu vysvětlím, co dělá každá obrazovka a proč jsou požadovány určité údaje. Kdykoliv mě můžete minimalizovat.',
      'ctx.voter.home_selection.title': 'Vyberte, co chcete zobrazit',
      'ctx.voter.home_selection.body': 'Vyberte, zda se chcete zúčastnit aktivních konzultací, nebo zkontrolovat, jak byl váš hlas započítán v již uzavřených konzultacích.',
      'ctx.voter.auth.login.title': 'Přihlásit se',
      'ctx.voter.auth.login.body': 'Přihlaste se zde pomocí svého existujícího e-mailu a hesla. Poprvé tady? Použijte kartu registrace.',
      'ctx.voter.register.overview.title': 'Vytvořte si účet',
      'ctx.voter.register.overview.body': 'Zde si vytváříte účet pro účast v Preferendum. Každé pole vysvětlím, jakmile jej budete vyplňovat — zemi, obec, datum narození, povolání a kontaktní údaje.',
      'ctx.voter.register.country.title': 'Země',
      'ctx.voter.register.country.body': 'Vaši zemi používáme pro kontext účtu a pro určení, na které konzultace máte nárok — mnoho konzultací je omezeno na konkrétní zemi nebo region.',
      'ctx.voter.register.commune.title': 'Obec / lokalita',
      'ctx.voter.register.commune.body': 'Vaše obec se používá pro konzultace s místním rozsahem a případně jako součást ekonomického kontextu vaší oblasti — nikdy k vaší identifikaci vůči ostatním uživatelům.',
      'ctx.voter.register.dob.title': 'Datum narození',
      'ctx.voter.register.dob.body': 'Váš věk určuje, na které konzultace máte nárok, pokud mají nastavené věkové rozmezí, a — když systém odhaduje rozsah příjmu, protože není uvedeno výslovné prohlášení — je to jeden ze signálů použitých pro tento odhad.',
      'ctx.voter.register.occupation.title': 'Povolání',
      'ctx.voter.register.occupation.body': 'Vaše povolání je porovnáváno se standardní klasifikací. Může to být kritérium cílení pro některé konzultace nebo kampaně a přispívá k odhadu rozsahu příjmu, pokud jej přímo neuvedete.',
      'ctx.voter.register.occupation.why': 'Vaše přesné povolání nikdy nezobrazujeme ani nesdílíme s ostatními uživateli — používá se pouze interně pro způsobilost a odhad.',
      'ctx.voter.register.company_size.title': 'Velikost společnosti',
      'ctx.voter.register.company_size.body': 'Velikost vaší společnosti poskytuje další ekonomický kontext. Tam, kde je implementována, přispívá k odhadu příjmu a může být kritériem cílení — ne všechny konzultace nebo kampaně ji však používají.',
      'ctx.voter.register.email.title': 'E-mail',
      'ctx.voter.register.email.body': 'Váš e-mail se používá pro přístup k účtu, k vaší verifikaci a k zasílání bezpečnostních kódů, když je to potřeba.',
      'ctx.voter.register.name.title': 'Celé jméno',
      'ctx.voter.register.name.body': 'Vaše jméno používáme k pozdějšímu ověření vaší identity (porovnáním s vaším dokladem totožnosti a selfie) a k oslovování vás v rámci platformy — nikdy se veřejně nezobrazuje ostatním uživatelům.',
      'ctx.voter.register.password.title': 'Heslo',
      'ctx.voter.register.password.body': 'Vaše heslo chrání přístup k vašemu účtu. Nikdy ho nesdílíme ani nezobrazujeme — nevidí ho ani náš vlastní tým.',
      'ctx.voter.register.national_id.title': 'Doklad totožnosti',
      'ctx.voter.register.national_id.body': 'Váš doklad pomáhá potvrdit, že jste skutečná a jedinečná osoba, a zabraňuje duplicitním účtům — nikdy se veřejně nezobrazuje ostatním uživatelům.',
      'ctx.voter.register.gender.title': 'Pohlaví',
      'ctx.voter.register.gender.body': 'Vaše pohlaví používáme pouze tehdy, když jej konkrétní konzultace stanoví jako kritérium způsobilosti — nemá to vliv na vaši účast v konzultacích, které to nevyžadují.',
      'ctx.voter.register.phone.title': 'Telefon',
      'ctx.voter.register.phone.body': 'Vaše telefonní číslo se používá pro ověření SMS a jako dodatečná vrstva zabezpečení vašeho účtu.',
      'ctx.voter.verify.overview.title': 'Ověření totožnosti',
      'ctx.voter.verify.overview.body': 'V této části potvrzujeme, že jste skutečná a jedinečná osoba, pomocí ověřovacího kódu a selfie. To chrání integritu konzultací.',
      'ctx.voter.verify.selfie.title': 'Ověření selfie',
      'ctx.voter.verify.selfie.body': 'Vaše selfie potvrzuje, že jste skutečná osoba a že odpovídá vašemu dokladu. Prefy nikdy nepřijímá ani neukládá vaši fotografii — přímo ji zpracovává ověřovací systém.',
      'ctx.voter.verify.document.title': 'Ověření dokladu',
      'ctx.voter.verify.document.body': 'Váš doklad totožnosti se používá pouze k potvrzení, kdo jste. Prefy nikdy nečte ani nezobrazuje údaje z vašeho dokladu — ani zde, ani na žádné jiné obrazovce.',
      'ctx.voter.consultations.title': 'Vaše konzultace',
      'ctx.voter.consultations.body': 'Zde vidíte konzultace, u kterých Preferendum určilo, že máte nárok, na základě kritérií nastavených pro každou z nich. Ne všechny konzultace používají stejná kritéria.',
      'ctx.voter.consultation.detail.title': 'Detail konzultace',
      'ctx.voter.consultation.detail.body': 'Tato obrazovka obsahuje otázku, kontext, názory ostatních účastníků a — pokud jsou k dispozici — výsledky. Pro přepínání mezi sekcemi použijte karty níže.',
